/// A single body line of a unified-diff hunk.
#[derive(Debug, Clone, PartialEq, Eq)]
enum BodyLine {
    Context(String),
    Del(String),
    Add(String),
}

impl BodyLine {
    fn text(&self) -> &str {
        match self {
            BodyLine::Context(s) | BodyLine::Del(s) | BodyLine::Add(s) => s,
        }
    }

    fn is_del(&self) -> bool {
        matches!(self, BodyLine::Del(_))
    }

    fn is_add(&self) -> bool {
        matches!(self, BodyLine::Add(_))
    }
