//! The agent: model + tools + message history + the tool-calling loop.

use std::collections::HashMap;
use std::sync::{Arc, Mutex};

use chrono::Utc;
use futures::StreamExt as _;
use rig::client::CompletionClient;
use rig::completion::message::ToolCall;
use rig::completion::{
    AssistantContent, CompletionModel, GetTokenUsage, Message, ToolDefinition, Usage,
};
use rig::providers::openai;
use rig::tool::PortableDynamicTool;
use serde::Serialize;
use tokio::sync::mpsc;

use crate::error::AgentError;

/// Default system prompt used when none is supplied.
pub const DEFAULT_SYSTEM_PROMPT: &str = "You are a helpful assistant running in an agent harness. \
You have access to tools. Use them when they help answer the user; otherwise answer directly. \
When a tool result comes back, incorporate it into your final answer. \
Do not re-run the same read-only tool with the same arguments within a turn: reuse the result \
you already have, because the result cannot have changed and re-running wastes resources.";

/// System prompt for task mode: long-horizon self-improvement work with
/// explicit workflow gates (mirrors the project's Rust workflow rules).
pub const TASK_SYSTEM_PROMPT: &str = "You are hānihi in task mode: a coding agent working on a Rust codebase. \
Work in small steps and verify with the build before declaring success. Workflow gates: \
run `cargo fmt` before staging changes; `cargo test` before committing; `cargo build` must pass; \
run `cargo clippy -- -D warnings` before finishing. Make changes as small git commits with \
descriptive messages. Never push. Study command output and trace files before retrying: if a \
command fails, read the error and fix the cause rather than repeating it. Verify your work with \
the build/test gates — do not assert success by eye. Before calling a tool, check whether an \
identical read-only call with a usable result already appears in this turn; reuse it instead of \
re-running.";

/// Read-only, deterministic tools whose results may be reused within a turn.
const CACHEABLE_TOOLS: &[&str] = &["read_file", "list_dir", "grep", "read_session_log", "echo"];

/// Tools that mutate the repository. A successful call invalidates the
/// per-turn read-only tool cache.
const WRITE_TOOLS: &[&str] = &["apply_patch", "write_file"];

/// Result of looking up a tool call in the per-turn cache.
enum ToolCallCacheLookup {
    /// An earlier identical call succeeded; reuse this rendered result.
    Hit(String),
    /// The identical read-only call has already been made too many times.
    DuplicateLimit { count: usize },
    /// Not cacheable, or the first time this call has been seen.
    Miss,
}

/// Per-turn cache of read-only tool results keyed by `name + '\u{1}' + args`.
#[derive(Debug, Default)]
struct ToolCallCache {
    results: HashMap<String, String>,
    counts: HashMap<String, usize>,
}

impl ToolCallCache {
    fn reset(&mut self) {
        self.results.clear();
        self.counts.clear();
    }

    fn key(name: &str, args: &serde_json::Value) -> String {
        format!("{name}\u{1}{args}")
    }

    fn lookup(&mut self, name: &str, args: &serde_json::Value) -> ToolCallCacheLookup {
        if !CACHEABLE_TOOLS.contains(&name) {
            return ToolCallCacheLookup::Miss;
        }
        let key = Self::key(name, args);
        let count = self.counts.entry(key.clone()).or_insert(0);
        *count += 1;
        if *count >= 3 {
            return ToolCallCacheLookup::DuplicateLimit { count: *count };
        }
        match self.results.get(&key) {
            Some(rendered) => ToolCallCacheLookup::Hit(rendered.clone()),
            None => ToolCallCacheLookup::Miss,
        }
    }

    fn store(&mut self, name: &str, args: &serde_json::Value, rendered: &str) {
        if CACHEABLE_TOOLS.contains(&name) {
            let key = Self::key(name, args);
            self.results.insert(key, rendered.to_string());
        }
    }

    fn invalidate_on_write(&mut self, name: &str) {
        if WRITE_TOOLS.contains(&name) {
            self.reset();
        }
    }
}

/// Result of one `Agent::run` invocation.
#[derive(Debug, Clone)]
pub struct TurnSummary {
    /// Final assistant text.
    pub text: String,
    /// Number of tool calls executed during the turn.
    pub tool_calls: usize,
    /// Total token usage across all model calls in the turn.
    pub usage: Usage,
    /// Final message history after the turn (for streaming — the agent's
    /// history is updated in the spawned task; the caller seeds it back).
    pub final_history: Vec<Message>,
}

/// A tool call carried in a [`StreamEvent::CompletionResponse`].
#[derive(Debug, Clone)]
pub struct StreamToolCall {
    pub id: String,
    pub name: String,
    pub arguments: serde_json::Value,
}

/// Events emitted during a streaming agent turn.
#[derive(Debug, Clone)]
pub enum StreamEvent {
    /// Delta of assistant text.
    TextDelta { text: String },
    /// Model has started a tool call (name known, arguments assembling).
    ToolCallStart { id: String, name: String },
    /// Fragment of tool call arguments (partial JSON).
    ToolCallArgs { id: String, args_delta: String },
    /// Tool call is complete and about to be executed.
    ToolCallReady {
        id: String,
        name: String,
        arguments: serde_json::Value,
    },
    /// Tool has executed successfully.
    ToolResult {
        id: String,
        name: String,
        /// Truncated preview of the result (for inline display).
        result_preview: String,
        /// Full rendered result (for session-log persistence).
        result: String,
    },
    /// A completion request was assembled and is about to be sent.
    CompletionRequest {
        ts: chrono::DateTime<Utc>,
        messages: serde_json::Value,
        tool_definitions: serde_json::Value,
    },
    /// A streaming completion response finished.
    CompletionResponse {
        ts: chrono::DateTime<Utc>,
        message_id: Option<String>,
        text: Option<String>,
        reasoning: Option<String>,
        tool_calls: Option<Vec<StreamToolCall>>,
        input_tokens: u64,
        output_tokens: u64,
    },
    /// Turn completed successfully.
    TurnComplete { summary: TurnSummary },
    /// An error occurred during the turn.
    Error { message: String },
}

/// Connect to an OpenAI-compatible chat completions endpoint (e.g. DeepSeek)
/// and return an agent bound to it.
///
/// The concrete model type is hidden behind `impl CompletionModel` so callers
/// never need to name it.
pub fn connect_chat_model(
    base_url: String,
    api_key: String,
    model: String,
) -> Result<Agent<impl CompletionModel + use<>>, AgentError> {
    connect_chat_model_with_prompt(base_url, api_key, model, DEFAULT_SYSTEM_PROMPT)
}

/// Like [`connect_chat_model`], but with a custom system prompt (e.g. the
/// task-mode prompt for self-improvement work).
pub fn connect_chat_model_with_prompt(
    base_url: String,
    api_key: String,
    model: String,
    system_prompt: &str,
) -> Result<Agent<impl CompletionModel + use<>>, AgentError> {
    let client = openai::CompletionsClient::builder()
        .api_key(&api_key)
        .base_url(&base_url)
        .build()
        .map_err(|e| AgentError::Rig(e.to_string()))?;
    let model = client.completion_model(&model);
    Ok(Agent::new(model, system_prompt))
}

/// A minimal tool-calling agent.
///
/// Generic over the rig [`CompletionModel`]; unit tests use rig's
/// `MockCompletionModel`, production uses the OpenAI-compatible client from
/// [`connect_chat_model`].
pub struct Agent<M: CompletionModel> {
    model: M,
    system_prompt: String,
    tools: Arc<Vec<PortableDynamicTool>>,
    history: Vec<Message>,
    max_turns: usize,
    tool_cache: Arc<Mutex<ToolCallCache>>,
}

impl<M: CompletionModel> Agent<M> {
    /// Create an agent with no tools and an empty history.
    pub fn new(model: M, system_prompt: impl Into<String>) -> Self {
        Self {
            model,
            system_prompt: system_prompt.into(),
            tools: Arc::new(Vec::new()),
            history: Vec::new(),
            max_turns: 10,
            tool_cache: Arc::new(Mutex::new(ToolCallCache::default())),
        }
    }

    /// The system prompt.
    pub fn system_prompt(&self) -> &str {
        &self.system_prompt
    }

    /// Register a tool. The agent exposes it to the model on the next turn.
    pub fn add_tool(&mut self, tool: PortableDynamicTool) {
        Arc::make_mut(&mut self.tools).push(tool);
    }

    /// Clone of the shared tool registry (for use in spawned tasks).
    fn tools_arc(&self) -> Arc<Vec<PortableDynamicTool>> {
        self.tools.clone()
    }

    /// Tool inventory (name, description, JSON schema).
    pub fn tool_definitions(&self) -> Vec<ToolDefinition> {
        self.tools.iter().map(|t| t.definition()).collect()
    }

    /// Number of registered tools.
    pub fn tool_count(&self) -> usize {
        self.tools.len()
    }

    /// Persistent message history (prior turns only).
    pub fn history(&self) -> &[Message] {
        &self.history
    }

    /// Maximum model turns per `run` invocation.
    pub fn max_turns(&self) -> usize {
        self.max_turns
    }

    /// Set the maximum model turns per `run` invocation.
    pub fn set_max_turns(&mut self, max_turns: usize) {
        self.max_turns = max_turns;
    }

    /// Clear the persistent message history.
    pub fn clear_history(&mut self) {
        self.history.clear();
    }

    /// Clear the per-turn read-only tool cache (start of a new turn).
    pub(crate) fn clear_tool_cache(&self) {
        self.tool_cache
            .lock()
            .expect("tool call cache lock")
            .reset();
    }

    /// Replace the persistent message history (e.g. from session replay).
    pub fn set_history(&mut self, history: Vec<Message>) {
        self.history = history;
    }

    /// Run a single completion call against the model.
    ///
    /// Assembles the request from `user_input` + persistent history +
    /// in-progress turn messages + tool definitions, sends it to the
    /// model, and returns the response. `Session` uses this to interpose
    /// logging between calls.
    pub(crate) async fn single_completion(
        &self,
        user_input: &str,
        turn_messages: &[Message],
    ) -> Result<rig::completion::CompletionResponse<M::Response>, AgentError> {
        let request = self
            .model
            .completion_request(Message::user(user_input))
            .preamble(self.system_prompt.clone())
            .messages(self.history.iter().chain(turn_messages.iter()).cloned())
            .tools(self.tool_definitions())
            .build();
        let response = self.model.completion(request).await?;
        Ok(response)
    }

    /// Run one user request to completion: model calls, tool execution, and
    /// follow-up model calls until the model answers without tool calls.
    pub async fn run(&mut self, user_input: &str) -> Result<TurnSummary, AgentError> {
        self.clear_tool_cache();
        let mut turn_messages: Vec<Message> = Vec::new();
        let mut tool_calls_total = 0usize;
        let mut usage_total = Usage::new();

        for _ in 0..self.max_turns {
            let request = self
                .model
                .completion_request(Message::user(user_input))
                .preamble(self.system_prompt.clone())
                .messages(self.history.iter().chain(turn_messages.iter()).cloned())
                .tools(self.tool_definitions())
                .build();

            let response = self.model.completion(request).await?;
            usage_total += response.usage;

            let mut text_parts = Vec::new();
            let mut tool_calls: Vec<ToolCall> = Vec::new();
            for content in response.choice.iter() {
                match content {
                    AssistantContent::Text(t) => text_parts.push(t.clone()),
                    AssistantContent::ToolCall(call) => tool_calls.push(call.clone()),
                    AssistantContent::Reasoning(_) | AssistantContent::Image(_) => {}
                }
            }

            if tool_calls.is_empty() {
                let text = text_parts
                    .iter()
                    .map(|t| t.text())
                    .collect::<Vec<_>>()
                    .join("\n");
                turn_messages.push(Message::assistant(text.clone()));
                self.commit_turn(user_input, turn_messages);
                return Ok(TurnSummary {
                    text,
                    tool_calls: tool_calls_total,
                    usage: usage_total,
                    final_history: self.history.clone(),
                });
            }

            let mut contents: Vec<AssistantContent> =
                text_parts.into_iter().map(AssistantContent::Text).collect();
            contents.extend(tool_calls.iter().cloned().map(AssistantContent::ToolCall));
            turn_messages.push(Message::Assistant {
                id: response.message_id,
                content: rig::OneOrMany::from_iter_optional(contents)
                    .expect("assistant message has at least one tool call"),
            });

            for call in &tool_calls {
                let output = self.execute_tool(call).await?;
                tool_calls_total += 1;
                turn_messages.push(Message::tool_result_with_call_id(
                    call.id.clone(),
                    call.call_id.clone(),
                    output,
                ));
            }
        }

        self.commit_turn(user_input, turn_messages);
        Err(AgentError::MaxTurns {
            turns: self.max_turns,
        })
    }

    /// Run one user turn with streaming output.
    ///
    /// Returns a channel receiver. The caller reads events as they arrive.
    /// The agent loop runs on a spawned task. After the stream completes,
    /// the caller should extract `final_history` from the `TurnComplete`
    /// event and call `set_history` to persist the new state.
    pub async fn run_streaming(
        &self,
        user_input: &str,
    ) -> Result<mpsc::Receiver<StreamEvent>, AgentError>
    where
        M: 'static,
        M::StreamingResponse: Send,
    {
        let (tx, rx) = mpsc::channel(32);
        let model = self.model.clone();
        let tools = self.tools_arc();
        let tool_cache = self.tool_cache.clone();
        let max_turns = self.max_turns;
        let system_prompt = self.system_prompt.clone();
        let mut history = self.history.clone();
        let user_input = user_input.to_string();

        tokio::spawn(async move {
            let result = run_streaming_loop(
                model,
                tools,
                &mut history,
                user_input,
                system_prompt,
                max_turns,
                &tx,
                tool_cache,
            )
            .await;
            // The agent's persistent history is returned to the caller via
            // `TurnComplete.final_history`; the caller seeds it back.
            let _ = result;
        });

        Ok(rx)
    }

    /// Dispatch a single tool call by name and render its output as text.
    pub(crate) async fn execute_tool(&self, call: &ToolCall) -> Result<String, AgentError> {
        execute_tool_with_cache(
            self.tools.as_slice(),
            &self.tool_cache,
            &call.function.name,
            call.function.arguments.clone(),
        )
        .await
    }

    /// Append the completed turn to the persistent history.
    pub(crate) fn commit_turn(&mut self, user_input: &str, turn_messages: Vec<Message>) {
        self.history.push(Message::user(user_input));
        self.history.extend(turn_messages);
    }
}

/// Build the JSON message list sent to the model, for `llm_prompt` log entries.
pub(crate) fn messages_for_log(
    system_prompt: &str,
    history: &[Message],
    turn_messages: &[Message],
    user_input: &str,
) -> Result<serde_json::Value, AgentError> {
    #[derive(Serialize)]
    struct LogMessage {
        role: String,
        content: serde_json::Value,
    }

    let mut msgs: Vec<LogMessage> = Vec::new();

    // System preamble.
    msgs.push(LogMessage {
        role: "system".into(),
        content: serde_json::Value::String(system_prompt.to_string()),
    });

    // Serialize each message via serde.
    fn msg_to_value(msg: &Message) -> Result<LogMessage, AgentError> {
        let v = serde_json::to_value(msg).map_err(|e| AgentError::Rig(e.to_string()))?;
        let role = v["role"].as_str().unwrap_or("unknown").to_string();
        Ok(LogMessage {
            role,
            content: v["content"].clone(),
        })
    }

    for m in history.iter().chain(turn_messages.iter()) {
        msgs.push(msg_to_value(m)?);
    }
    // Current user message.
    msgs.push(LogMessage {
        role: "user".into(),
        content: serde_json::Value::String(user_input.to_string()),
    });

    serde_json::to_value(&msgs).map_err(|e| AgentError::Rig(e.to_string()))
}

/// Execute one tool call, reusing cached results for repeated identical
/// read-only calls within the same turn.
async fn execute_tool_with_cache(
    tools: &[PortableDynamicTool],
    cache: &Mutex<ToolCallCache>,
    name: &str,
    args: serde_json::Value,
) -> Result<String, AgentError> {
    {
        let mut cache = cache.lock().expect("tool call cache lock");
        match cache.lookup(name, &args) {
            ToolCallCacheLookup::Hit(rendered) => return Ok(rendered),
            ToolCallCacheLookup::DuplicateLimit { count } => {
                return Ok(format!(
                    "duplicate call skipped: '{name}' with identical arguments was already called {count} times this turn; reuse an earlier result"
                ));
            }
            ToolCallCacheLookup::Miss => {}
        }
    }

    let tool = tools
        .iter()
        .find(|t| t.name() == name)
        .ok_or_else(|| AgentError::Tool {
            name: name.to_string(),
            message: "unknown tool".into(),
        })?;
    let output = tool
        .execute(args.clone())
        .await
        .map_err(|e| AgentError::Tool {
            name: name.to_string(),
            message: e.to_string(),
        })?;
    let rendered = output.render();

    let mut cache = cache.lock().expect("tool call cache lock");
    cache.store(name, &args, &rendered);
    cache.invalidate_on_write(name);
    Ok(rendered)
}

/// The inner streaming loop, run on a spawned task.
///
/// Consumes the model stream, executes tools when complete tool calls
/// arrive, and sends [`StreamEvent`]s to the caller.
async fn run_streaming_loop<M: CompletionModel>(
    model: M,
    tools: Arc<Vec<PortableDynamicTool>>,
    history: &mut Vec<Message>,
    user_input: String,
    system_prompt: String,
    max_turns: usize,
    tx: &mpsc::Sender<StreamEvent>,
    tool_cache: Arc<Mutex<ToolCallCache>>,
) -> Result<TurnSummary, AgentError>
where
    M::StreamingResponse: Send,
{
    tool_cache.lock().expect("tool call cache lock").reset();
    let mut turn_messages: Vec<Message> = Vec::new();
    let mut tool_calls_total: usize = 0;
    let mut usage_total = Usage::new();

    for _turn in 0..max_turns {
        // Build the request and report it before sending.
        let tool_definitions = tools.iter().map(|t| t.definition()).collect::<Vec<_>>();
        let messages_json = messages_for_log(&system_prompt, history, &turn_messages, &user_input)?;
        let tool_definitions_json = serde_json::to_value(&tool_definitions)?;
        let _ = tx
            .send(StreamEvent::CompletionRequest {
                ts: Utc::now(),
                messages: messages_json,
                tool_definitions: tool_definitions_json,
            })
            .await;

        let request = model
            .completion_request(Message::user(user_input.clone()))
            .preamble(system_prompt.clone())
            .messages(history.iter().chain(turn_messages.iter()).cloned())
            .tools(tool_definitions)
            .build();

        let mut stream = model
            .stream(request)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        // Track tool calls, their results, and per-call text/reasoning/usage
        // during this model call.
        let mut pending_tool_calls: Vec<ToolCall> = Vec::new();
        let mut pending_results: Vec<(ToolCall, String)> = Vec::new();
        let mut text_buf = String::new();
        let mut reasoning_buf = String::new();
        let mut call_usage = Usage::new();

        while let Some(item) = stream.next().await {
            match item {
                Ok(rig::streaming::StreamedAssistantContent::Text(t)) => {
                    let delta = t.text().to_string();
                    text_buf.push_str(&delta);
                    let _ = tx.send(StreamEvent::TextDelta { text: delta }).await;
                }
                Ok(rig::streaming::StreamedAssistantContent::ToolCallDelta {
                    id, content, ..
                }) => {
                    use rig::streaming::ToolCallDeltaContent;
                    match content {
                        ToolCallDeltaContent::Name(name) => {
                            let _ = tx
                                .send(StreamEvent::ToolCallStart {
                                    id: id.clone(),
                                    name: name.clone(),
                                })
                                .await;
                        }
                        ToolCallDeltaContent::Delta(args) => {
                            let _ = tx
                                .send(StreamEvent::ToolCallArgs {
                                    id: id.clone(),
                                    args_delta: args,
                                })
                                .await;
                        }
                    }
                }
                Ok(rig::streaming::StreamedAssistantContent::ToolCall { tool_call, .. }) => {
                    let _ = tx
                        .send(StreamEvent::ToolCallReady {
                            id: tool_call.id.clone(),
                            name: tool_call.function.name.clone(),
                            arguments: tool_call.function.arguments.clone(),
                        })
                        .await;

                    // Execute the tool, reusing cached results for repeated
                    // identical read-only calls within this turn.
                    let name = tool_call.function.name.clone();
                    match execute_tool_with_cache(
                        tools.as_slice(),
                        &tool_cache,
                        &name,
                        tool_call.function.arguments.clone(),
                    )
                    .await
                    {
                        Ok(rendered) => {
                            let preview = if rendered.len() > 200 {
                                format!("{}…", rendered.chars().take(200).collect::<String>())
                            } else {
                                rendered.clone()
                            };
                            let _ = tx
                                .send(StreamEvent::ToolResult {
                                    id: tool_call.id.clone(),
                                    name: name.clone(),
                                    result_preview: preview,
                                    result: rendered.clone(),
                                })
                                .await;
                            tool_calls_total += 1;
                            pending_results.push((tool_call.clone(), rendered));
                        }
                        Err(e) => {
                            let _ = tx
                                .send(StreamEvent::Error {
                                    message: e.to_string(),
                                })
                                .await;
                            return Err(e);
                        }
                    }
                    pending_tool_calls.push(tool_call);
                }
                Ok(rig::streaming::StreamedAssistantContent::Final(r)) => {
                    let usage = r.token_usage();
                    usage_total += usage;
                    call_usage = usage;
                }
                Ok(rig::streaming::StreamedAssistantContent::ReasoningDelta {
                    reasoning, ..
                }) => {
                    reasoning_buf.push_str(&reasoning);
                }
                Ok(rig::streaming::StreamedAssistantContent::Reasoning(r)) => {
                    if reasoning_buf.is_empty() {
                        reasoning_buf = r.display_text();
                    } else {
                        reasoning_buf.push('\n');
                        reasoning_buf.push_str(&r.display_text());
                    }
                }
                Ok(rig::streaming::StreamedAssistantContent::Unknown(_)) => {}
                Err(e) => {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: e.to_string(),
                        })
                        .await;
                    return Err(AgentError::Rig(e.to_string()));
                }
            }
        }

        // Capture message_id and report the completed response.
        let message_id = stream.message_id.clone();
        let response_text = (!text_buf.is_empty()).then(|| text_buf.clone());
        let response_reasoning = (!reasoning_buf.is_empty()).then(|| reasoning_buf.clone());
        let response_tool_calls = (!pending_tool_calls.is_empty()).then(|| {
            pending_tool_calls
                .iter()
                .map(|call| StreamToolCall {
                    id: call.id.clone(),
                    name: call.function.name.clone(),
                    arguments: call.function.arguments.clone(),
                })
                .collect()
        });
        let _ = tx
            .send(StreamEvent::CompletionResponse {
                ts: Utc::now(),
                message_id: message_id.clone(),
                text: response_text,
                reasoning: response_reasoning,
                tool_calls: response_tool_calls,
                input_tokens: call_usage.input_tokens,
                output_tokens: call_usage.output_tokens,
            })
            .await;

        // If no tool calls were made, the turn is complete.
        if pending_tool_calls.is_empty() {
            turn_messages.push(Message::assistant(text_buf.clone()));
            history.push(Message::user(user_input));
            history.extend(turn_messages);
            let summary = TurnSummary {
                text: text_buf,
                tool_calls: tool_calls_total,
                usage: usage_total,
                final_history: history.clone(),
            };
            let _ = tx
                .send(StreamEvent::TurnComplete {
                    summary: summary.clone(),
                })
                .await;
            return Ok(summary);
        }

        // Tool calls were executed. Build the assistant message and loop.
        let mut contents: Vec<AssistantContent> = Vec::new();
        if !text_buf.is_empty() {
            contents.push(AssistantContent::Text(rig::completion::message::Text::new(
                text_buf,
            )));
        }
        contents.extend(
            pending_tool_calls
                .iter()
                .cloned()
                .map(AssistantContent::ToolCall),
        );
        turn_messages.push(Message::Assistant {
            id: message_id,
            content: rig::OneOrMany::from_iter_optional(contents)
                .expect("assistant message has content"),
        });

        // Push tool results AFTER the assistant message.
        for (call, rendered) in pending_results {
            turn_messages.push(Message::tool_result_with_call_id(
                call.id,
                call.call_id,
                rendered,
            ));
        }
    }

    // Max turns exceeded.
    history.push(Message::user(user_input));
    history.extend(turn_messages);
    let _ = tx
        .send(StreamEvent::Error {
            message: format!("exceeded maximum of {max_turns} model turns"),
        })
        .await;
    Err(AgentError::MaxTurns { turns: max_turns })
}

#[cfg(test)]
mod tests {
    use super::*;
    use rig::test_utils::{MockCompletionModel, MockTurn};

    fn echo_agent() -> Agent<MockCompletionModel> {
        let mut agent = Agent::new(MockCompletionModel::text("unused"), "test system");
        agent.add_tool(crate::tool::builtin_echo());
        agent
    }

    #[tokio::test]
    async fn test_simple_text_reply() {
        let mut agent = echo_agent();
        let summary = agent.run("hi").await.expect("run succeeds");
        assert_eq!(summary.text, "unused");
        assert_eq!(summary.tool_calls, 0);
        assert_eq!(agent.history().len(), 2);
    }

    #[tokio::test]
    async fn test_tool_call_round_trip() {
        let model = MockCompletionModel::from_turns([
            MockTurn::tool_call("call_1", "echo", serde_json::json!({"text": "ping"})),
            MockTurn::text("echoed: ping"),
        ]);
        let mut agent = Agent::new(model, "test system");
        agent.add_tool(crate::tool::builtin_echo());

        let summary = agent.run("echo ping").await.expect("run succeeds");
        assert_eq!(summary.text, "echoed: ping");
        assert_eq!(summary.tool_calls, 1);

        let history = agent.history();
        assert_eq!(history.len(), 4);
    }

    #[tokio::test]
    async fn test_max_turns_exceeded() {
        let model = MockCompletionModel::from_turns(std::iter::repeat_n(
            MockTurn::tool_call("call_x", "echo", serde_json::json!({"text": "x"})),
            50,
        ));
        let mut agent = Agent::new(model, "test system");
        agent.add_tool(crate::tool::builtin_echo());
        agent.set_max_turns(3);

        let err = agent.run("loop").await.expect_err("run must fail");
        assert!(matches!(err, AgentError::MaxTurns { turns: 3 }));
    }

    #[tokio::test]
    async fn test_unknown_tool_fails() {
        let model = MockCompletionModel::from_turns([MockTurn::tool_call(
            "call_1",
            "nonexistent",
            serde_json::json!({}),
        )]);
        let mut agent = Agent::new(model, "test system");
        let err = agent.run("do it").await.expect_err("run must fail");
        assert!(matches!(err, AgentError::Tool { .. }));
    }

    /// A read-only, deterministic tool whose results can be reused within a
    /// turn. Two identical calls on the same turn must execute the underlying
    /// tool only once.
    #[tokio::test]
    async fn test_duplicate_read_only_tool_call_is_deduplicated() {
        let executions = Arc::new(std::sync::atomic::AtomicUsize::new(0));
        let counter = executions.clone();

        // The tool is named after a real builtin ("read_file") so the
        // cacheable-tool whitelist applies, but the callback counts
        // executions without touching the filesystem.
        let counting_tool = PortableDynamicTool::new(
            "read_file",
            "A read-only tool that counts executions.",
            serde_json::json!({
                "type": "object",
                "properties": {
                "path": { "type": "string" }
                },
                "required": ["path"]
            }),
            move |args: serde_json::Value| {
                let counter = counter.clone();
                Box::pin(async move {
                    use std::sync::atomic::Ordering;
                    counter.fetch_add(1, Ordering::SeqCst);
                    use rig::tool::ToolOutput;
                    Ok(ToolOutput::text(
                        args.get("path")
                            .and_then(|v| v.as_str())
                            .unwrap_or_default(),
                    ))
                })
            },
        );

        let model = MockCompletionModel::from_turns([
            MockTurn::tool_call("call_1", "read_file", serde_json::json!({"path": "a"})),
            MockTurn::tool_call("call_2", "read_file", serde_json::json!({"path": "a"})),
            MockTurn::text("done"),
        ]);
        let mut agent = Agent::new(model, "test system");
        agent.add_tool(counting_tool);

        let summary = agent
            .run("read the same file twice")
            .await
            .expect("run succeeds");
        // The two identical calls are deduplicated but still counted once.
        assert_eq!(summary.tool_calls, 2);
        use std::sync::atomic::Ordering;
        assert_eq!(executions.load(Ordering::SeqCst), 1);
    }

    #[test]
    fn messages_for_log_includes_system_history_and_user() {
        let history = vec![Message::user("earlier")];
        let turn_messages = vec![Message::assistant("partial")];
        let value =
            messages_for_log("system", &history, &turn_messages, "now").expect("build messages");

        let arr = value.as_array().expect("messages is an array");
        assert_eq!(arr.len(), 3);
        assert_eq!(arr[0]["role"], "system");
        assert_eq!(arr[0]["content"], "system");
        assert_eq!(arr[1]["role"], "user");
        assert_eq!(arr[2]["role"], "assistant");
    }
}

//! Session management: named, persistent conversation containers with
//! append-only JSONL event logs.
//!
//! A [`Session`] holds the on-disk state (metadata, event log, lock) for a
//! named conversation. It does not own an [`Agent`]; the caller passes the
//! agent to [`Session::run`], which wraps the agent loop with full logging.
//!
//! [`SessionManager`] owns the working directory and handles creation,
//! opening, and closing of sessions.
//!
//! [`Agent`]: crate::agent::Agent

pub mod lock;
pub mod log;

use std::collections::HashMap;
use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use chrono::Utc;
use rig::completion::message::{ToolCall, ToolFunction};
use rig::completion::{AssistantContent, CompletionModel, Message};
use tokio::sync::mpsc;
use uuid::Uuid;

use self::lock::SessionGuard;
use self::log::{ErrorStage, LogEntry, LogWriter, ToolCallData, UsageData};
use crate::agent::{Agent, StreamEvent, TurnSummary, messages_for_log};
use crate::error::AgentError;

/// Errors produced by session operations.
#[derive(Debug)]
pub enum SessionError {
    /// The session name is reserved and cannot be created manually.
    ReservedName(String),
    /// A session with this name already exists.
    AlreadyExists(String),
    /// The requested session was not found.
    NotFound(String),
    /// The session is locked by another process.
    Locked(String),
    /// An I/O error occurred.
    Io(io::Error),
    /// A JSON (de)serialization error occurred.
    Json(serde_json::Error),
    /// A line in the event log could not be parsed.
    LogLine { line: usize, message: String },
}

impl std::fmt::Display for SessionError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SessionError::ReservedName(name) => {
                write!(f, "'{name}' is reserved and cannot be created manually")
            }
            SessionError::AlreadyExists(name) => {
                write!(f, "session '{name}' already exists")
            }
            SessionError::NotFound(name) => {
                write!(
                    f,
                    "session '{name}' not found — use --new-session to create it"
                )
            }
            SessionError::Locked(name) => {
                write!(f, "session '{name}' is locked by another process")
            }
            SessionError::Io(e) => write!(f, "io error: {e}"),
            SessionError::Json(e) => write!(f, "json error: {e}"),
            SessionError::LogLine { line, message } => {
                write!(f, "log line {line}: {message}")
            }
        }
    }
}

impl std::error::Error for SessionError {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            SessionError::Io(e) => Some(e),
            SessionError::Json(e) => Some(e),
            _ => None,
        }
    }
}

impl From<io::Error> for SessionError {
    fn from(e: io::Error) -> Self {
        SessionError::Io(e)
    }
}

impl From<serde_json::Error> for SessionError {
    fn from(e: serde_json::Error) -> Self {
        SessionError::Json(e)
    }
}

impl From<AgentError> for SessionError {
    fn from(e: AgentError) -> Self {
        SessionError::Io(io::Error::other(e.to_string()))
    }
}

/// Manages the set of active sessions within a working directory.
#[derive(Debug)]
pub struct SessionManager {
    working_dir: PathBuf,
    sessions: HashMap<String, Session>,
}

impl SessionManager {
    /// Create a new manager. `working_dir` is resolved relative to the
    /// process cwd at startup (the caller must resolve it).
    pub fn new(working_dir: impl Into<PathBuf>) -> Self {
        Self {
            working_dir: working_dir.into(),
            sessions: HashMap::new(),
        }
    }

    /// Path to the sessions directory: `<working_dir>/sessions/`.
    pub fn sessions_dir(&self) -> PathBuf {
        self.working_dir.join("sessions")
    }

    /// Check whether a session exists (by name) on disk.
    pub fn exists(&self, name: &str) -> bool {
        self.session_dir(name).exists()
    }

    /// List session names found on disk.
    pub fn list(&self) -> io::Result<Vec<String>> {
        let dir = self.sessions_dir();
        if !dir.exists() {
            return Ok(Vec::new());
        }
        let mut names = Vec::new();
        for entry in fs::read_dir(&dir)? {
            let entry = entry?;
            if entry.file_type()?.is_dir()
                && let Some(name) = entry.file_name().to_str()
            {
                names.push(name.to_string());
            }
        }
        names.sort();
        Ok(names)
    }

    /// Create a new session. Fails if the name is reserved or already exists.
    pub fn create(
        &mut self,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if name == "default-session" {
            return Err(SessionError::ReservedName(name.into()));
        }
        if self.exists(name) {
            return Err(SessionError::AlreadyExists(name.into()));
        }
        let session = Session::create(&self.sessions_dir(), name, model, system_prompt)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Create the reserved auto session (`default-session`).
    ///
    /// Only the CLI's implicit auto-create path may call this; `create`
    /// rejects reserved names so users cannot claim them explicitly.
    pub fn create_default(
        &mut self,
        model: &str,
        system_prompt: &str,
    ) -> Result<&mut Session, SessionError> {
        if self.exists("default-session") {
            return Err(SessionError::AlreadyExists("default-session".into()));
        }
        let session = Session::create(
            &self.sessions_dir(),
            "default-session",
            model,
            system_prompt,
        )?;
        self.sessions.insert("default-session".to_string(), session);
        Ok(self
            .sessions
            .get_mut("default-session")
            .expect("just inserted"))
    }

    /// Open an existing session. Fails if it doesn't exist or is locked.
    pub fn open(&mut self, name: &str) -> Result<&mut Session, SessionError> {
        if self.sessions.contains_key(name) {
            return self
                .sessions
                .get_mut(name)
                .ok_or_else(|| SessionError::NotFound(name.into()));
        }
        if !self.exists(name) {
            return Err(SessionError::NotFound(name.into()));
        }
        let session = Session::open(&self.sessions_dir(), name)?;
        self.sessions.insert(name.to_string(), session);
        Ok(self.sessions.get_mut(name).expect("just inserted"))
    }

    /// Close a session: writes `session_closed`, flushes the log, and
    /// releases the filesystem lock.
    pub fn close(&mut self, name: &str) -> Result<(), SessionError> {
        let mut session = self
            .sessions
            .remove(name)
            .ok_or_else(|| SessionError::NotFound(name.into()))?;
        let turn = session.turn;
        session.log_entry(&LogEntry::session_closed(
            Utc::now(),
            turn,
            session.id.to_string(),
            session.name.clone(),
        ))?;
        drop(session); // releases lock
        Ok(())
    }

    /// Path to a specific session directory.
    fn session_dir(&self, name: &str) -> PathBuf {
        self.sessions_dir().join(name)
    }
}

/// A named, persistent session that holds on-disk state and a log writer.
///
/// Created and managed via [`SessionManager`]; not constructed directly.
/// Call [`Session::run`] with an agent to execute a turn with full logging.
#[derive(Debug)]
pub struct Session {
    /// Unique identifier for this session (stable across restarts).
    pub id: Uuid,
    /// Human-readable session name.
    pub name: String,
    /// When the session was first created.
    pub created_at: chrono::DateTime<Utc>,
    /// Model name in use.
    pub model: String,
    /// Current turn number (monotonically increasing).
    pub turn: u64,

    /// Path to the session directory on disk.
    root: PathBuf,
    /// Append-only event log writer.
    log: LogWriter,
    /// Filesystem lock held for the lifetime of this session.
    _guard: SessionGuard,
}

impl Session {
    /// Path to the session directory on disk.
    pub fn root(&self) -> &Path {
        &self.root
    }

    /// Create a new session on disk. Internal — use `SessionManager::create`.
    fn create(
        sessions_dir: &Path,
        name: &str,
        model: &str,
        system_prompt: &str,
    ) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        fs::create_dir_all(&dir)?;

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        let id = Uuid::new_v4();
        let created_at = Utc::now();

        // Write session.json.
        let meta = serde_json::json!({
            "id": id.to_string(),
            "name": name,
            "created_at": created_at.to_rfc3339(),
            "model": model,
            "system_prompt": system_prompt,
        });
        fs::write(
            dir.join("session.json"),
            serde_json::to_string_pretty(&meta)?,
        )?;

        // Open the event log.
        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        // Log creation and first open.
        let now = Utc::now();
        log.write_entry(&LogEntry::session_created(
            now,
            0,
            id.to_string(),
            name.to_string(),
            model.to_string(),
            system_prompt.to_string(),
        ))?;
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model: model.to_string(),
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Open an existing session. Internal — use `SessionManager::open`.
    fn open(sessions_dir: &Path, name: &str) -> Result<Self, SessionError> {
        let dir = sessions_dir.join(name);
        if !dir.exists() {
            return Err(SessionError::NotFound(name.into()));
        }

        let guard = SessionGuard::acquire(&dir).map_err(|_| SessionError::Locked(name.into()))?;

        // Read session.json.
        let meta_path = dir.join("session.json");
        let meta_bytes = fs::read(&meta_path)?;
        let meta: serde_json::Value = serde_json::from_slice(&meta_bytes)?;
        let id: Uuid = meta["id"]
            .as_str()
            .and_then(|s| s.parse().ok())
            .unwrap_or_else(Uuid::new_v4);
        let created_at: chrono::DateTime<Utc> = meta["created_at"]
            .as_str()
            .and_then(|s| chrono::DateTime::parse_from_rfc3339(s).ok())
            .map(|dt| dt.with_timezone(&Utc))
            .unwrap_or_else(Utc::now);
        let model = meta["model"].as_str().unwrap_or("unknown").to_string();

        let log_path = dir.join("events.jsonl");
        let mut log = LogWriter::open(&log_path)?;

        let now = Utc::now();
        log.write_entry(&LogEntry::session_opened(
            now,
            0,
            id.to_string(),
            name.to_string(),
        ))?;

        Ok(Self {
            id,
            name: name.to_string(),
            created_at,
            model,
            turn: 0,
            root: dir,
            log,
            _guard: guard,
        })
    }

    /// Run one user turn with full logging.
    ///
    /// Wraps the agent loop: for each model call and tool execution, an
    /// event is written to the session log. Returns the same `TurnSummary`
    /// as [`Agent::run`].
    pub async fn run<M: CompletionModel>(
        &mut self,
        agent: &mut Agent<M>,
        provider: &str,
        model_name: &str,
        user_input: &str,
    ) -> Result<TurnSummary, AgentError> {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut turn_messages: Vec<Message> = Vec::new();
        let mut tool_calls_total = 0usize;
        let mut usage_total = rig::completion::Usage::new();

        for _ in 0..agent.max_turns() {
            // Build and log the prompt.
            let tools = agent.tool_definitions();
            let messages_json = messages_for_log(
                agent.system_prompt(),
                agent.history(),
                &turn_messages,
                user_input,
            )?;
            let tools_json =
                serde_json::to_value(&tools).map_err(|e| AgentError::Rig(e.to_string()))?;
            self.log_entry(&LogEntry::llm_prompt(
                Utc::now(),
                self.turn,
                provider.to_string(),
                model_name.to_string(),
                messages_json,
                tools_json,
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // Call the model.
            let response = agent.single_completion(user_input, &turn_messages).await?;
            usage_total += response.usage;

            // Extract content from the response.
            let mut text_parts: Vec<rig::completion::message::Text> = Vec::new();
            let mut reasoning_parts: Vec<String> = Vec::new();
            let mut tool_calls: Vec<ToolCall> = Vec::new();
            for content in response.choice.iter() {
                match content {
                    AssistantContent::Text(t) => text_parts.push(t.clone()),
                    AssistantContent::ToolCall(call) => tool_calls.push(call.clone()),
                    AssistantContent::Reasoning(r) => {
                        reasoning_parts.push(r.display_text());
                    }
                    AssistantContent::Image(_) => {}
                }
            }

            // Log the response.
            let response_text = if text_parts.is_empty() {
                None
            } else {
                Some(
                    text_parts
                        .iter()
                        .map(|t| t.text())
                        .collect::<Vec<_>>()
                        .join("\n"),
                )
            };
            let response_reasoning = if reasoning_parts.is_empty() {
                None
            } else {
                Some(reasoning_parts.join("\n"))
            };
            let response_tool_calls: Option<Vec<ToolCallData>> = if tool_calls.is_empty() {
                None
            } else {
                Some(
                    tool_calls
                        .iter()
                        .map(|c| ToolCallData {
                            id: c.id.clone(),
                            name: c.function.name.clone(),
                            arguments: c.function.arguments.clone(),
                        })
                        .collect(),
                )
            };
            self.log_entry(&LogEntry::llm_response(
                Utc::now(),
                self.turn,
                response.message_id.clone(),
                response_text.clone(),
                response_reasoning,
                response_tool_calls.clone(),
                UsageData {
                    input_tokens: response.usage.input_tokens as u32,
                    output_tokens: response.usage.output_tokens as u32,
                },
            ))
            .map_err(|e| AgentError::Rig(e.to_string()))?;

            // No tool calls: turn complete.
            if tool_calls.is_empty() {
                let text = response_text.unwrap_or_default();
                turn_messages.push(Message::assistant(text.clone()));
                agent.commit_turn(user_input, turn_messages);

                self.log_entry(&LogEntry::turn_complete(
                    Utc::now(),
                    self.turn,
                    text.clone(),
                    tool_calls_total,
                ))
                .map_err(|e| AgentError::Rig(e.to_string()))?;

                return Ok(TurnSummary {
                    text,
                    tool_calls: tool_calls_total,
                    usage: usage_total,
                    final_history: agent.history().to_vec(),
                });
            }

            // Record the assistant message and execute tools.
            let mut contents: Vec<AssistantContent> =
                text_parts.into_iter().map(AssistantContent::Text).collect();
            contents.extend(tool_calls.iter().cloned().map(AssistantContent::ToolCall));
            turn_messages.push(Message::Assistant {
                id: response.message_id,
                content: rig::OneOrMany::from_iter_optional(contents)
                    .expect("assistant message has at least one tool call"),
            });

            for call in &tool_calls {
                let tool_args = call.function.arguments.clone();
                match agent.execute_tool(call).await {
                    Ok(output) => {
                        tool_calls_total += 1;
                        self.log_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            self.turn,
                            call.id.clone(),
                            call.call_id.clone().unwrap_or_else(|| call.id.clone()),
                            call.function.name.clone(),
                            tool_args,
                            output.clone(),
                        ))
                        .map_err(|e| AgentError::Rig(e.to_string()))?;
                        turn_messages.push(Message::tool_result_with_call_id(
                            call.id.clone(),
                            call.call_id.clone(),
                            output,
                        ));
                    }
                    Err(e) => {
                        // Log error and bail.
                        self.log_entry(&LogEntry::error(
                            Utc::now(),
                            self.turn,
                            ErrorStage::ToolExecution,
                            e.to_string(),
                        ))
                        .map_err(|se| AgentError::Rig(se.to_string()))?;
                        agent.commit_turn(user_input, turn_messages);
                        return Err(e);
                    }
                }
            }
        }

        // Max turns exceeded.
        self.log_entry(&LogEntry::error(
            Utc::now(),
            self.turn,
            ErrorStage::LlmCall,
            format!("exceeded maximum of {} model turns", agent.max_turns()),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;
        agent.commit_turn(user_input, turn_messages);
        Err(AgentError::MaxTurns {
            turns: agent.max_turns(),
        })
    }

    /// Run one user turn with streaming output and full logging.
    ///
    /// Like [`run`], but model output arrives token-by-token through a
    /// channel. The caller reads [`StreamEvent`]s while the agent loop
    /// runs concurrently. Prompt, response, tool execution, completion,
    /// and error events are logged from the stream.
    ///
    /// [`StreamEvent`]: crate::agent::StreamEvent
    pub async fn run_streaming<M: CompletionModel + 'static>(
        &mut self,
        agent: &mut Agent<M>,
        provider: &str,
        model_name: &str,
        user_input: &str,
    ) -> Result<mpsc::Receiver<StreamEvent>, AgentError>
    where
        M::StreamingResponse: Send,
    {
        self.turn += 1;

        // Log user input.
        self.log_entry(&LogEntry::user_input(
            Utc::now(),
            self.turn,
            user_input.to_string(),
        ))
        .map_err(|e| AgentError::Rig(e.to_string()))?;

        let mut agent_rx = agent
            .run_streaming(user_input)
            .await
            .map_err(|e| AgentError::Rig(e.to_string()))?;

        let (tx, rx) = mpsc::channel(32);

        // Spawn a task that reads from the agent stream, writes log entries
        // for prompt/response/tool execution/completion/error, and forwards
        // events to the session's own channel.
        let turn = self.turn;
        let log_path = self.events_path();
        let provider = provider.to_string();
        let model_name = model_name.to_string();

        tokio::spawn(async move {
            let mut log_writer = match LogWriter::open(&log_path) {
                Ok(writer) => writer,
                Err(e) => {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: format!("re-open session log for streaming: {e}"),
                        })
                        .await;
                    return;
                }
            };

            let mut tool_calls_total: usize = 0;

            // Track tool arguments captured at ToolCallReady so the
            // tool_execution entry can log the real values (not a
            // placeholder).
            let mut pending_args: HashMap<String, serde_json::Value> = HashMap::new();

            while let Some(event) = agent_rx.recv().await {
                // Translate agent stream events into log entries. On writer
                // failure, report an error and stop logging further events.
                let write_result = match &event {
                    StreamEvent::ToolCallReady {
                        id,
                        name: _,
                        arguments,
                    } => {
                        pending_args.insert(id.clone(), arguments.clone());
                        Ok(())
                    }
                    StreamEvent::CompletionRequest {
                        ts,
                        messages,
                        tool_definitions,
                    } => log_writer.write_entry(&LogEntry::llm_prompt(
                        *ts,
                        turn,
                        provider.clone(),
                        model_name.clone(),
                        messages.clone(),
                        tool_definitions.clone(),
                    )),
                    StreamEvent::CompletionResponse {
                        ts,
                        message_id,
                        text,
                        reasoning,
                        tool_calls,
                        input_tokens,
                        output_tokens,
                    } => log_writer.write_entry(&LogEntry::llm_response(
                        *ts,
                        turn,
                        message_id.clone(),
                        text.clone(),
                        reasoning.clone(),
                        tool_calls.as_ref().map(|calls| {
                            calls
                                .iter()
                                .map(|c| ToolCallData {
                                    id: c.id.clone(),
                                    name: c.name.clone(),
                                    arguments: c.arguments.clone(),
                                })
                                .collect()
                        }),
                        UsageData {
                            input_tokens: *input_tokens as u32,
                            output_tokens: *output_tokens as u32,
                        },
                    )),
                    StreamEvent::ToolResult {
                        id,
                        name,
                        result,
                        result_preview: _,
                    } => {
                        tool_calls_total += 1;
                        let args = pending_args.remove(id).unwrap_or(serde_json::Value::Null);
                        // Log the real arguments and full result.
                        log_writer.write_entry(&LogEntry::tool_execution(
                            Utc::now(),
                            turn,
                            id.clone(),
                            id.clone(), // call_id same as tool_call_id (simplified)
                            name.clone(),
                            args,
                            result.clone(),
                        ))
                    }
                    StreamEvent::TurnComplete { summary } => {
                        log_writer.write_entry(&LogEntry::turn_complete(
                            Utc::now(),
                            turn,
                            summary.text.clone(),
                            tool_calls_total,
                        ))
                    }
                    StreamEvent::Error { message } => log_writer.write_entry(&LogEntry::error(
                        Utc::now(),
                        turn,
                        ErrorStage::LlmCall,
                        message.clone(),
                    )),
                    StreamEvent::TextDelta { .. }
                    | StreamEvent::ToolCallStart { .. }
                    | StreamEvent::ToolCallArgs { .. } => Ok(()),
                };

                if let Err(e) = write_result {
                    let _ = tx
                        .send(StreamEvent::Error {
                            message: format!("writing session log: {e}"),
                        })
                        .await;
                    let _ = tx.send(event).await;
                    break;
                }

                let _ = tx.send(event).await;
            }
        });

        Ok(rx)
    }

    /// Append an entry to the event log.
    pub fn log_entry(&mut self, entry: &LogEntry) -> Result<(), SessionError> {
        self.log.write_entry(entry)?;
        Ok(())
    }

    /// Read the full session metadata from `session.json`.
    pub fn read_meta(&self) -> Result<serde_json::Value, SessionError> {
        let meta_path = self.root.join("session.json");
        let bytes = fs::read(&meta_path)?;
        let value: serde_json::Value = serde_json::from_slice(&bytes)?;
        Ok(value)
    }

    /// Path to the events log file.
    pub fn events_path(&self) -> PathBuf {
        self.root.join("events.jsonl")
    }

    /// Path to the session metadata file.
    pub fn meta_path(&self) -> PathBuf {
        self.root.join("session.json")
    }

    /// Reconstruct agent message history from the event log.
    ///
    /// Walks the log, builds `Message` values for each completed turn, and
    /// stops at the last `turn_complete` or `error` boundary. Partial turns
    /// (events after the last complete turn without a close) are dropped.
    ///
    /// Lifecycle events (`session_created`, `session_opened`, etc.) and
    /// `llm_prompt` entries are skipped — they're not needed for history
    /// reconstruction.
    pub fn replay_history(&self) -> Result<Vec<Message>, SessionError> {
        let entries = self.events()?;
        let mut messages: Vec<Message> = Vec::new();
        let mut safe_len: usize = 0;
        // Track whether the last assistant message had tool calls.
        let mut last_had_tool_calls = false;

        for entry in &entries {
            match entry {
                LogEntry::UserInput { data, .. } => {
                    messages.push(Message::user(data.text.clone()));
                    last_had_tool_calls = false;
                }
                LogEntry::LlmResponse { data, .. } => {
                    if let Some(ref tcs) = data.tool_calls {
                        let contents: Vec<AssistantContent> = tcs
                            .iter()
                            .map(|tc| {
                                AssistantContent::ToolCall(ToolCall::new(
                                    tc.id.clone(),
                                    ToolFunction {
                                        name: tc.name.clone(),
                                        arguments: tc.arguments.clone(),
                                    },
                                ))
                            })
                            .collect();
                        messages.push(Message::Assistant {
                            id: data.message_id.clone(),
                            content: rig::OneOrMany::from_iter_optional(contents)
                                .expect("assistant message has at least one tool call"),
                        });
                        last_had_tool_calls = true;
                    } else if let Some(ref text) = data.text {
                        messages.push(Message::assistant(text.clone()));
                        last_had_tool_calls = false;
                    }
                }
                LogEntry::ToolExecution { data, .. } => {
                    // Streaming sessions may lack llm_response entries. If
                    // the last assistant had no tool calls, synthesize one
                    // for this specific tool execution.
                    let was_synthetic = !last_had_tool_calls;
                    if was_synthetic {
                        let tc = ToolCall::new(
                            data.tool_call_id.clone(),
                            ToolFunction {
                                name: data.name.clone(),
                                arguments: data.arguments.clone(),
                            },
                        );
                        messages.push(Message::Assistant {
                            id: None,
                            content: rig::OneOrMany::one(AssistantContent::ToolCall(tc)),
                        });
                        last_had_tool_calls = true;
                    }
                    let call_id = if data.call_id.is_empty() {
                        data.tool_call_id.clone()
                    } else {
                        data.call_id.clone()
                    };
                    messages.push(Message::tool_result_with_call_id(
                        data.tool_call_id.clone(),
                        Some(call_id),
                        data.result.clone(),
                    ));
                    // If we synthesized the assistant, reset so the
                    // next tool_exec gets its own assistant too.
                    if was_synthetic {
                        last_had_tool_calls = false;
                    }
                }
                LogEntry::TurnComplete { .. } | LogEntry::Error { .. } => {
                    // End of a completed turn — mark all accumulated
                    // messages as safe.
                    safe_len = messages.len();
                }
                // Skip lifecycle and prompt entries.
                LogEntry::SessionCreated { .. }
                | LogEntry::SessionOpened { .. }
                | LogEntry::SessionClosed { .. }
                | LogEntry::LlmPrompt { .. } => {}
            }
        }

        // Truncate to the last complete turn boundary.
        messages.truncate(safe_len);
        Ok(messages)
    }

    // --- Derived property accessors (Step 4) ---

    /// Parse all events from the log file and return them.
    pub fn events(&self) -> Result<Vec<LogEntry>, SessionError> {
        let path = self.events_path();
        if !path.exists() {
            return Ok(Vec::new());
        }
        let contents = fs::read_to_string(&path)?;
        self::log::parse_log_strict(&contents).map_err(|e| SessionError::LogLine {
            line: e.line,
            message: e.message,
        })
    }

    /// Compute cumulative token usage from all `llm_response` events.
    pub fn cumulative_usage(&self) -> Result<(u64, u64), SessionError> {
        let mut total_in: u64 = 0;
        let mut total_out: u64 = 0;
        for entry in self.events()? {
            if let LogEntry::LlmResponse { data, .. } = &entry {
                total_in += data.usage.input_tokens as u64;
                total_out += data.usage.output_tokens as u64;
            }
        }
        Ok((total_in, total_out))
    }

    /// Timestamp of the most recent `session_opened` event.
    pub fn last_opened_at(&self) -> Result<Option<chrono::DateTime<Utc>>, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::SessionOpened { .. }));
        Ok(last.map(|e| e.ts()))
    }

    /// Total turns from the most recent `turn_complete` event.
    pub fn total_turns(&self) -> Result<u64, SessionError> {
        let events = self.events()?;
        let last = events
            .iter()
            .rev()
            .find(|e| matches!(e, LogEntry::TurnComplete { .. }));
        Ok(last.map(|e| e.turn()).unwrap_or(0))
    }

    /// Per-call model latencies computed from prompt/response timestamp
    /// pairs. Returns a vector of (ts, latency_ms) for each completed call.
    pub fn latencies(&self) -> Result<Vec<(chrono::DateTime<Utc>, i64)>, SessionError> {
        let events = self.events()?;
        let mut latencies = Vec::new();
        let mut pending_prompt_ts: Option<chrono::DateTime<Utc>> = None;

        for entry in &events {
            match entry {
                LogEntry::LlmPrompt { ts, .. } => {
                    pending_prompt_ts = Some(*ts);
                }
                LogEntry::LlmResponse { ts, .. } => {
                    if let Some(prompt_ts) = pending_prompt_ts.take() {
                        let latency_ms = (*ts - prompt_ts).num_milliseconds();
                        latencies.push((*ts, latency_ms));
                    }
                }
                _ => {}
            }
        }

        Ok(latencies)
    }
}

